-- Historical (2026-10-24): read-only release fingerprint verification.
with d as(select * from public.documents where source_key like 'law:%') select jsonb_build_object('documents',(select jsonb_agg(jsonb_build_object('document_id',d.id,'source_key',d.source_key,'title',d.title,'text_sha256',d.content_sha256,'document_fingerprint',md5(to_jsonb(d)::text),'chunks',(select count(*) from public.document_chunks c where c.document_id=d.id),'chunks_fingerprint',(select md5(string_agg(md5(to_jsonb(c)::text),'' order by c.id)) from public.document_chunks c where c.document_id=d.id),'input_fingerprint',(select md5(to_jsonb(i)::text) from public.ingest_text_inputs i where i.document_id=d.id),'jobs_fingerprint',(select md5(string_agg(md5(to_jsonb(j)::text),'' order by j.id)) from public.ingest_jobs j where j.document_id=d.id))) from d),'global_documents',(select count(*) from public.documents),'global_chunks',(select count(*) from public.document_chunks),'law_jobs',(select count(*) from public.ingest_jobs j join d on d.id=j.document_id),'law_embed_cost',(select sum(embed_cost_usd) from public.ingest_jobs j join d on d.id=j.document_id),'law_ocr_cost',(select sum(ocr_cost_usd) from public.ingest_jobs j join d on d.id=j.document_id),'listing_count',(select count(*) from public.desk_rows where tier='law' and feature='NCLT / NCLAT (Insolvency)')) baseline;
select public.law_listing_page('{"filter":[{"col":"availability","value":"indexed"}],"pageSize":200}'::jsonb);
